export async function retry<T>(fn: () => Promise<T>) {
  for (let attempt = 0; ; attempt++) {
    try {
      return await fn();
    } catch (error) {
      if (attempt === 4) throw error;
      await sleep(Math.min(2 ** attempt * 500, 30_000));
    }
  }
}
